// ---- events (flat wire truth) ---------------------------------------------


export type AgentEventType = 'agent_start' | 'agent_end' | 'turn_start' | 'turn_end' | 'message_start' | 'message_update' | 'message_end' | 'tool_execution_start' | 'tool_execution_update' | 'tool_execution_end' | 'retry_attempt'

/** The flat wire truth of `codec.serialize_event`: `type` discriminates,
 * every other key is conditional on it. Handwritten per-event unions in
 * types-events.ts refine this and must stay assignable to it. */
export interface AgentEventWire {
  type: string
  tool_name?: string
  tool_call_id?: string
  is_error?: boolean
  assistant_event?: Record<string, unknown>
  attempt?: number
  max_retries?: number
  delay_ms?: number
  model?: string
  error?: string
  message?: Record<string, unknown>
  new_messages?: Array<Record<string, unknown>>
  args?: string
  result_text?: string
  details?: string
  tool_stats?: Record<string, unknown>
  partial_result?: string
  duration_ms?: number
  termination?: string
  detail?: string
}


// ---- host surface (RpcHost) -----------------------------------------------


/** Host ops the registry fully declares; the stubbed families (see protocol.HOST_PARTIAL) never appear here. */

